<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);$id=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT * FROM donation_campaigns WHERE id=? AND hospital_id=?');$q->execute([$id,(int)$hospital['id']]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Campaign not found.');}
if(request_method('POST')){Csrf::verify();$action=$_POST['action']??'';if($action==='status'){$status=$_POST['status']??'';if(in_array($status,['active','closed','cancelled'],true)){db()->prepare('UPDATE donation_campaigns SET status=? WHERE id=?')->execute([$status,$id]);audit('campaign_status_updated','campaign',$id,['status'=>$status]);flash('success','Campaign status updated.');}}elseif($action==='attendance'){$reg=(int)($_POST['registration_id']??0);$att=$_POST['attendance_status']??'';if(in_array($att,['pending','attended','no_show'],true)){db()->prepare('UPDATE campaign_registrations SET attendance_status=? WHERE id=? AND campaign_id=?')->execute([$att,$reg,$id]);audit('campaign_attendance_updated','campaign',$id,['registration_id'=>$reg,'attendance'=>$att]);flash('success','Attendance updated.');}}redirect('hospital/campaign-detail.php?id='.$id);}
$r=db()->prepare("SELECT cr.*,u.full_name,u.email,u.phone,dp.blood_group FROM campaign_registrations cr JOIN users u ON u.id=cr.donor_id JOIN donor_profiles dp ON dp.user_id=u.id WHERE cr.campaign_id=? ORDER BY cr.appointment_time,u.full_name");$r->execute([$id]);$rows=$r->fetchAll();$pageTitle='Campaign Detail';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><?=hospital_nav($user)?><div class="dash-head"><div><div class="eyebrow">Campaign management</div><h1><?=e($c['title'])?></h1><p><?=e($c['event_date'])?> · <?=e(substr($c['start_time'],0,5))?>–<?=e(substr($c['end_time'],0,5))?> · <?=e($c['location'])?></p></div><form method="post" class="mini-actions"><?=Csrf::field()?><input type="hidden" name="id" value="<?=e((string)$id)?>"><input type="hidden" name="action" value="status"><select name="status"><option value="active" <?=$c['status']==='active'?'selected':''?>>Active</option><option value="closed" <?=$c['status']==='closed'?'selected':''?>>Closed</option><option value="cancelled" <?=$c['status']==='cancelled'?'selected':''?>>Cancelled</option></select><button class="btn btn-sm">Save Status</button></form></div><h2>Donor appointments</h2><div class="table-wrap"><table class="table"><thead><tr><th>Donor</th><th>Blood</th><th>Appointment</th><th>Booking</th><th>Attendance</th><th>Update</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No donor appointments yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><br><span class="small"><?=e($r['email'])?></span></td><td><?=e($r['blood_group'])?></td><td><?=e(substr($r['appointment_time'],0,5))?></td><td><?=e($r['status'])?></td><td><span class="badge <?=$r['attendance_status']==='attended'?'green':($r['attendance_status']==='no_show'?'red':'amber')?>"><?=e($r['attendance_status'])?></span></td><td><form method="post" class="mini-actions"><?=Csrf::field()?><input type="hidden" name="id" value="<?=e((string)$id)?>"><input type="hidden" name="action" value="attendance"><input type="hidden" name="registration_id" value="<?=e((string)$r['id'])?>"><select name="attendance_status"><option value="pending">Pending</option><option value="attended">Attended</option><option value="no_show">No show</option></select><button class="btn btn-sm">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section>
<?php require dirname(dirname(__DIR__)).'/src/templates/footer.php';?>
